MQL:
db.airlines.aggregate([
  { $unwind: { path: "$flights", preserveNullAndEmptyArrays: false } },
  { $group: {
      _id: {
        Abbreviation: { $ifNull: ["$Abbreviation", "(unknown)"] },
        route: { $concat: ["$flights.SourceAirport", "-", "$flights.DestAirport"] }
      },
      flight_count: { $sum: 1 }
  } },
  { $match: { flight_count: { $gt: 3 } } },
  { $project: {
      _id: 0,
      Abbreviation: "$_id.Abbreviation",
      route: "$_id.route",
      flight_count: 1
  } }
])
